const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '植物细胞结构示意图' },
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '细胞核' },
      { kind: 'text', payload: '液泡' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var s = Math.min(W / 700, H / 520);
    var ox = (W - 700 * s) / 2;
    var oy = (H - 520 * s) / 2;

    function P(p) { return [ox + p[0] * s, oy + p[1] * s]; }
    function mid(a, b) { return [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2]; }
    function smoothClosed(pts) {
      var n = pts.length;
      var cmds = [];
      var m0 = mid(pts[n - 1], pts[0]);
      cmds.push(['M', m0[0], m0[1]]);
      for (var i = 0; i < n; i++) {
        var p = pts[i];
        var q = pts[(i + 1) % n];
        var m = mid(p, q);
        cmds.push(['Q', p[0], p[1], m[0], m[1]]);
      }
      cmds.push(['Z']);
      return cmds;
    }
    function shrink(pts, c, k) {
      var out = [];
      for (var i = 0; i < pts.length; i++) {
        out.push([c[0] + (pts[i][0] - c[0]) * k, c[1] + (pts[i][1] - c[1]) * k]);
      }
      return out;
    }
    function conv(pts) {
      var out = [];
      for (var i = 0; i < pts.length; i++) { out.push(P(pts[i])); }
      return out;
    }

    var cellOuter = [[110, 120], [350, 88], [580, 140], [610, 330], [490, 450], [200, 460], [86, 300]];
    var vacDesign = [[235, 270], [305, 175], [445, 185], [515, 285], [455, 360], [310, 350]];

    var wallPath = smoothClosed(conv(cellOuter));
    var cytoPath = smoothClosed(conv(shrink(cellOuter, [347, 270], 0.95)));
    var vacPath = smoothClosed(conv(vacDesign));

    var nc = P([215, 378]);
    var nucPath = visualSdk.circle(nc[0], nc[1], 46 * s);
    var nl = P([228, 368]);
    var nucleolusPath = visualSdk.circle(nl[0], nl[1], 14 * s);

    var lw0 = P([505, 66]);
    var lw1 = P([503, 129]);
    var leadWall = [['M', lw0[0], lw0[1]], ['L', lw1[0], lw1[1]]];
    var ln0 = P([162, 476]);
    var ln1 = P([191, 417]);
    var leadNuc = [['M', ln0[0], ln0[1]], ['L', ln1[0], ln1[1]]];
    var dotWall = visualSdk.circle(lw1[0], lw1[1], 5 * s);
    var dotNuc = visualSdk.circle(ln1[0], ln1[1], 5 * s);

    return {
      schemaVersion: 1,
      sceneId: 'plant-cell',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'wall', commands: wallPath },
        { id: 'cyto', commands: cytoPath },
        { id: 'vacRing', commands: vacPath },
        { id: 'vac', commands: vacPath },
        { id: 'nucRing', commands: nucPath },
        { id: 'nuc', commands: nucPath },
        { id: 'nucleolus', commands: nucleolusPath },
        { id: 'leadWall', commands: leadWall },
        { id: 'leadNuc', commands: leadNuc },
        { id: 'dotWall', commands: dotWall },
        { id: 'dotNuc', commands: dotNuc }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'wall', fill: '#8fae5b', stroke: { width: 6 * s } },
          { type: 'path', pathId: 'cyto', fill: '#f1f8e9' },
          { type: 'path', pathId: 'vacRing', fill: '#69a6c9', stroke: { width: 6 * s } },
          { type: 'path', pathId: 'vac', fill: '#cfe8f5' },
          { type: 'path', pathId: 'nucRing', fill: '#8a63ad', stroke: { width: 6 * s } },
          { type: 'path', pathId: 'nuc', fill: '#dcc6ec' },
          { type: 'path', pathId: 'nucleolus', fill: '#6f4391' },
          { type: 'path', pathId: 'leadWall', fill: '#4a5f70', stroke: { width: 2 * s } },
          { type: 'path', pathId: 'leadNuc', fill: '#4a5f70', stroke: { width: 2 * s } },
          { type: 'path', pathId: 'dotWall', fill: '#4a5f70' },
          { type: 'path', pathId: 'dotNuc', fill: '#4a5f70' },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: P([30, 34])[0], y: P([30, 34])[1] }, hAlign: 'left', vAlign: 'top', color: '#5b6b7a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: P([505, 62])[0], y: P([505, 62])[1] }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: P([110, 500])[0], y: P([110, 500])[1] }, hAlign: 'left', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: P([378, 271])[0], y: P([378, 271])[1] }, hAlign: 'center', vAlign: 'middle', color: '#1d4459' }
        ]
      }
    };
  }
};
